// src/runtime/create-runtime/input-hooks.ts
function createRuntimeInputHooks(options) {
  const { beforeInputHook, beforeRenderOutputHook } = options;
  function runHook(hook, text, source, errorLabel) {
    if (!hook)
      return text;
    try {
      const next = hook({ text, source });
      if (next === null)
        return null;
      if (typeof next === "string")
        return next;
      return text;
    } catch (error) {
      console.error(errorLabel, error);
      return text;
    }
  }
  return {
    runBeforeInputHook: (text, source) => runHook(beforeInputHook, text, source, "[restty] beforeInput hook error:"),
    runBeforeRenderOutputHook: (text, source) => runHook(beforeRenderOutputHook, text, source, "[restty] beforeRenderOutput hook error:")
  };
}

// src/runtime/create-runtime/clipboard-paste.ts
function readPastePayloadFromDataTransfer(dataTransfer) {
  if (!dataTransfer)
    return null;
  const text = dataTransfer.getData("text/plain") || "";
  return text ? {
    kind: "text",
    text
  } : null;
}

// src/runtime/create-runtime/format-utils.ts
function formatPasteText(text, bracketedPasteEnabled) {
  if (!bracketedPasteEnabled)
    return text;
  return `\x1B[200~${text}\x1B[201~`;
}

